INSERT INTO zoho_import.notes ("note_record_id", "person_type", "person_record_id", "person_name", "note_title", "note_content", "note_owner", "created_by", "created_time", "modified_time") VALUES
  ('zcrm_1579374000178765053', 'contact', 'zcrm_1579374000166722001', 'Cory Miller', NULL, '1/15/26<br>Called cory back after he left a VM. Telehealth texted him so he called back in. i let him know they were jst calling due to him trying to set up ana ppointment. he has had his appointment and is now good to go <br>AJ', 'Concierge', 'Concierge', '2026-01-15 13:21:57', '2026-01-15 13:21:57'),
  ('zcrm_1579374000178786027', 'contact', 'zcrm_1579374000143461021', 'Julie Faucett', NULL, '1-15-26 Julie will likely choose Premium Care. No longer does pap screening due to a surgery years ago. She chose $2500/$487+$75 = $562 + $25 annual fee and I waived the $100 since she they were  members previously. I mentioned ways of helping Mark to quit smoking which she was excited to hear such as hypnosis and acupuncture. I told her it takes proof of quitting for 1 year with Dr. note and/or proof via blood labs, etc.  All set for Feb. 1st start date.', 'Wendy Scipione - SR VP National Sales Advisor', 'Wendy Scipione - SR VP National Sales Advisor', '2026-01-15 13:18:47', '2026-01-15 13:18:47'),
  ('zcrm_1579374000178760120', 'contact', 'zcrm_1579374000178796006', 'Andrea Boyle', NULL, 'Member &amp; Ch $5000 IUA Care +', 'Patti Baron', 'Patti Baron', '2026-01-15 13:14:15', '2026-01-15 13:14:15'),
  ('zcrm_1579374000178765048', 'contact', 'zcrm_1579374000175210002', 'Steven Ezell', NULL, '1/15/26<br>michelle called to find out how to use her RX benefits with Rx valet and how to go through the quote process as well. I walked her through using her app and rx valet and where to find her card. Also explained how to use the rx valet for quotes on other medications<br>AJ', 'Concierge', 'Concierge', '2026-01-15 13:13:17', '2026-01-15 13:13:17'),
  ('zcrm_1579374000178760112', 'contact', 'zcrm_1579374000178794006', 'Sean Kelly', NULL, 'Member &amp; Fam $2500 IUA Care +', 'Patti Baron', 'Patti Baron', '2026-01-15 13:10:15', '2026-01-15 13:10:15'),
  ('zcrm_1579374000178760098', 'contact', 'zcrm_1579374000178804001', 'James Burns', NULL, 'Member Only $5000 IUA Secure', 'Patti Baron', 'Patti Baron', '2026-01-15 13:03:02', '2026-01-15 13:03:02'),
  ('zcrm_1579374000178786019', 'contact', 'zcrm_1579374000172130002', 'Tami Schweitzer', NULL, '1-15-26 After much go around she finally landed on Cigna Connect Flex Bronze 7200. She will try to pay the cash price for meds to get better prices. They don''t go to the dr. very much. They just do the wellness screenings. They will be moving and this network will remain the same and bigger than Anthem''s Essential plans. She''s familiar with Cigna and likes them. So, that became the winner in the decision making process. She said UCH has accepted Cigna in the past for her husband. Hopefully that will continue to be true. If not, she''s ok with it since they barely go there. Meds for husband are testosterone, albuterol, anestrazole. They all looked affordable on GoodRX.', 'Wendy Scipione - SR VP National Sales Advisor', 'Wendy Scipione - SR VP National Sales Advisor', '2026-01-15 12:44:41', '2026-01-15 12:45:44'),
